<script setup lang="ts">
import {onMounted,ref} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {request,post} from '../api/client'
import {ElMessageBox} from 'element-plus'
interface Asset{id:string;title:string;source:string;outputs:{kind:string;path:string}[]}
interface Row{ordinal:number;assetId:string;path:string;state:string;message:string;digest:string}
interface Batch{id:string;state:string;digest:string;expiresAt:string;items:Row[]}
const route=useRoute(),router=useRouter(),paths=ref(''),preview=ref<{path:string;url?:string;content?:string;valid:boolean;message?:string}[]>([]),assets=ref<Asset[]>([]),selected=ref<string[]>([]),batch=ref<Batch>(),busy=ref(false),error=ref(''),q=ref('')
const labels:Record<string,string>={preview:'等待批准',running:'执行中',succeeded:'修复完成',partial:'部分完成 / 含跳过项',ready:'原文完整',missing:'待恢复缺失文件',staged:'已登记恢复意图',repaired:'已修复',needs_reconcile:'任务中断 / 需明确恢复',blocked:'跳过 / 需核对'}
async function batchPreview(){busy.value=true;error.value='';try{preview.value=await post('/strm/batch-preview',{paths:paths.value.split(/\r?\n/).filter(s=>s.trim())})}catch(e){error.value=e instanceof Error?e.message:'批量预览失败'}finally{busy.value=false}}
async function loadAssets(){busy.value=true;error.value='';try{assets.value=(await request<{items:Asset[]}>(`/library/outputs?kind=strm&page=1&pageSize=100&q=${encodeURIComponent(q.value)}`)).items;selected.value=[]}catch(e){error.value=e instanceof Error?e.message:'资产读取失败'}finally{busy.value=false}}
async function check(){busy.value=true;error.value='';try{batch.value=await post('/strm/repairs/preview',{assetIds:selected.value});await router.replace({query:{...route.query,repairId:batch.value!.id}})}catch(e){error.value=e instanceof Error?e.message:'检查失败'}finally{busy.value=false}}
async function refreshBatch(){const id=batch.value?.id||String(route.query.repairId||'');if(!id)return;busy.value=true;error.value='';try{batch.value=await request(`/strm/repairs/${id}`)}catch(e){error.value=e instanceof Error?e.message:'批次读取失败'}finally{busy.value=false}}
async function approve(){if(!batch.value)return;try{await ElMessageBox.confirm('仅恢复可证明原文的缺失STRM；不覆盖已修改文件、不旋转文件Key、不处理NFO。','批准批量STRM修复',{confirmButtonText:'明确批准修复',cancelButtonText:'取消',type:'warning'});busy.value=true;error.value='';batch.value=await post(`/strm/repairs/${batch.value.id}/approve`,{digest:batch.value.digest,confirm:true})}catch(e){if(e==='cancel'||e==='close')return;error.value=e instanceof Error?e.message:'结果尚未确认，请刷新现有批次状态，不重新创建或盲目重放'}finally{busy.value=false}}
async function resume(){if(!batch.value)return;try{await ElMessageBox.confirm('核对并恢复该已批准批次，沿用原始修复意图；不会覆盖手工文件或生成新Key。','恢复STRM修复任务',{confirmButtonText:'明确恢复任务',cancelButtonText:'取消',type:'warning'});busy.value=true;batch.value=await post(`/strm/repairs/${batch.value.id}/retry`,{digest:batch.value.digest,confirm:true})}catch(e){if(e==='cancel'||e==='close')return;error.value=e instanceof Error?e.message:'请先刷新批次核对状态'}finally{busy.value=false}}
onMounted(()=>{void loadAssets();if(route.query.repairId)void refreshBatch()})
</script>
<template>
 <el-alert v-if="error" :title="error" type="error" :closable="false"/>
 <section class="panel tool-section"><div class="panel-title"><div><h2>批量链接预览</h2><p class="field-hint">每行一个实际云盘完整路径，最多100条；只预览，不写入服务器或声称可播放。</p></div></div><label for="strm-batch-paths">云盘路径列表</label><el-input id="strm-batch-paths" v-model="paths" type="textarea" :rows="5" placeholder="/115/媒体/电影一.mkv&#10;/115/媒体/电影二.mkv"/><el-button type="primary" :loading="busy" :disabled="!paths.trim()" @click="batchPreview">批量预览链接</el-button><div v-for="(row,i) in preview" :key="i" class="preview-row"><strong>{{row.path}}</strong><span>{{row.valid?'已生成固定入口':row.message}}</span><el-input v-if="row.valid" :model-value="row.content" type="textarea" :rows="2" readonly :aria-label="`第${i+1}条STRM预览`"/></div></section>
 <section class="panel tool-section"><div class="panel-title"><div><h2>批量修复STRM</h2><p class="field-hint">检查托管输出，保持原始正文、文件级Key和媒体文件；手工改动和证据不足的文件不会覆盖。</p></div><el-button :loading="busy" @click="loadAssets">刷新托管资产</el-button></div><div class="repair-filter"><el-input v-model="q" aria-label="修复资产关键词" placeholder="标题或云盘路径" clearable @keyup.enter="loadAssets"/><el-button @click="loadAssets">筛选资产</el-button></div><el-checkbox-group v-model="selected" class="repair-assets"><el-checkbox v-for="asset in assets" :key="asset.id" :value="asset.id"><span>{{asset.title||'未确认标题'}} · {{asset.outputs.filter(o=>o.kind==='strm').length}} 份STRM</span></el-checkbox></el-checkbox-group><el-empty v-if="!busy&&!assets.length" description="暂无托管STRM资产"/><el-button :disabled="!selected.length" :loading="busy" @click="check">检查并预览修复（{{selected.length}}）</el-button>
 <section v-if="batch" class="repair-batch"><div class="panel-title"><div><h3>{{labels[batch.state]||batch.state}}</h3><p class="field-hint">批次 {{batch.id}} · 预览有效至 {{new Date(batch.expiresAt).toLocaleString('zh-CN')}}</p></div><el-button :loading="busy" @click="refreshBatch">刷新批次状态</el-button></div><ul><li v-for="row in batch.items" :key="row.ordinal"><el-tag :type="row.state==='blocked'?'warning':row.state==='repaired'||row.state==='ready'?'success':'info'">{{labels[row.state]||row.state}}</el-tag><code>{{row.path||row.assetId}}</code><p>{{row.message}}</p></li></ul><el-button v-if="batch.state==='preview'" type="primary" :loading="busy" :disabled="!batch.items.some(r=>r.state==='missing')" @click="approve">批准批量修复</el-button><el-button v-if="batch.state==='needs_reconcile'" :loading="busy" @click="resume">核对后恢复此批次</el-button><p class="field-hint">没有可安全修复项时不会执行。请求结果未知时只刷新此批次；服务器恢复意图持久化，不自动重新上传源媒体。</p></section></section>
</template>
<style scoped>.tool-section{margin-top:24px}.tool-section>label{display:block;margin-bottom:12px}.tool-section>.el-button{margin-top:16px;min-height:44px}.preview-row{display:flex;flex-direction:column;gap:12px;margin-top:20px;border-top:1px solid var(--border);padding-top:20px;overflow-wrap:anywhere}.repair-filter{display:flex;gap:12px;margin:16px 0}.repair-assets{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.repair-assets :deep(.el-checkbox){margin:0;min-height:44px;height:auto;white-space:normal}.repair-assets :deep(.el-checkbox__label){white-space:normal;overflow-wrap:anywhere}.repair-batch{margin-top:24px;border-top:1px solid var(--border);padding-top:24px}.repair-batch ul{list-style:none;padding:0}.repair-batch li{padding:16px 0;border-bottom:1px solid var(--border);display:flex;flex-wrap:wrap;gap:12px}.repair-batch li code{overflow-wrap:anywhere;min-width:0;flex:1}.repair-batch li p{flex-basis:100%;color:var(--muted);margin:0;line-height:1.7}.repair-batch .panel-title{gap:16px;flex-wrap:wrap}@media(max-width:680px){.repair-assets{grid-template-columns:1fr}.repair-batch li code{flex-basis:100%}}</style>
